'use strict';

// MODULES //

var addon = require( './../src/addon.node' );


// MAIN //

/**
* Computes the cross product of two double-precision floating-point input strided arrays and assigns the results to an output strided array.
*
* @param {Float64Array} x - first input array
* @param {integer} strideX - stride length for `x`
* @param {Float64Array} y - second input array
* @param {integer} strideY - stride length for `y`
* @param {Float64Array} z - output array
* @param {integer} strideZ - stride length for `z`
* @returns {Float64Array} output array
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var x = new Float64Array( [ 1.0, 2.0, 3.0 ] );
* var y = new Float64Array( [ 4.0, 5.0, 6.0 ] );
* var z = new Float64Array( [ 0.0, 0.0, 0.0 ] );
*
* dcross( x, 1, y, 1, z, 1 );
* // z => <Float64Array>[ -3.0, 6.0, -3.0 ]
*/
function dcross( x, strideX, y, strideY, z, strideZ ) {
	addon( x, strideX, y, strideY, z, strideZ );
	return z;
}


// EXPORTS //

module.exports = dcross;
